#!/usr/bin/env python3
"""AssignHub Notification Center — safe one-click installer.

Put next to manage.py and run:
  python apply_assignhub_notifications.py --check
  python apply_assignhub_notifications.py
"""
import argparse
import base64
import datetime
import json
import os
from pathlib import Path
import shutil
import sys
import tempfile
import zlib

PAYLOAD_B64 = ""
PATCHES_B64 = ""


def payload_files():
    return json.loads(zlib.decompress(base64.b64decode(PAYLOAD_B64)).decode("utf-8"))


def source_patches():
    return json.loads(base64.b64decode(PATCHES_B64).decode("utf-8"))


def patch_existing(root):
    updates = {}
    patches = source_patches()
    for relpath, replacements in patches.items():
        path = root / relpath
        if not path.is_file():
            raise RuntimeError("Required existing file not found: " + relpath)
        original = path.read_text(encoding="utf-8-sig")
        updated = original
        for old, new, marker in replacements:
            if marker in updated:
                continue
            matches = updated.count(old)
            if matches != 1:
                raise RuntimeError(
                    f"{relpath}: expected one source anchor, found {matches}. "
                    "The installer stopped without changes."
                )
            updated = updated.replace(old, new, 1)
        if updated != original:
            updates[relpath] = updated
    return updates


def plan(root):
    if not (root / "manage.py").is_file() or not (root / "assignments/models.py").is_file():
        raise RuntimeError("Place script inside AssignHub project root beside manage.py.")
    existing = patch_existing(root)
    added = {}
    for relpath, text in payload_files().items():
        path = root / relpath
        if path.exists():
            if not path.is_file() or path.read_text(encoding="utf-8-sig") != text:
                raise RuntimeError("New module path exists with DIFFERENT content: " + relpath)
        else:
            added[relpath] = text
    for relpath, text in {**existing, **added}.items():
        if relpath.endswith(".py"):
            compile(text, relpath, "exec")
    return existing, added


def main():
    parser = argparse.ArgumentParser(description="Install additive AssignHub Notification Center")
    parser.add_argument("--check", action="store_true", help="Preflight validation only, no writes")
    args = parser.parse_args()
    root = Path(__file__).resolve().parent
    try:
        existing, added = plan(root)
    except (OSError, RuntimeError, ValueError, SyntaxError) as exc:
        print(f"PREFLIGHT FAILED: {exc}", file=sys.stderr)
        return 1
    if args.check:
        print("PREFLIGHT PASSED — no files changed.")
        print(f"Existing files to patch: {len(existing)} | New files: {len(added)}")
        return 0
    if not existing and not added:
        print("Notification Center already installed; no changes needed.")
        return 0

    stamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S_%f")
    backup = root.parent / "AssignHub_Notification_Backups" / stamp
    changed = []
    backup.mkdir(parents=True, exist_ok=False)
    try:
        for relpath in existing:
            copy = backup / relpath
            copy.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(root / relpath, copy)
        for relpath, content in {**existing, **added}.items():
            destination = root / relpath
            destination.parent.mkdir(parents=True, exist_ok=True)
            fd, tmp = tempfile.mkstemp(prefix=".ah-notice-", dir=str(destination.parent))
            try:
                with os.fdopen(fd, "w", encoding="utf-8", newline="\n") as out:
                    out.write(content)
                os.replace(tmp, destination)
                changed.append(relpath)
            finally:
                if os.path.exists(tmp):
                    os.unlink(tmp)
    except Exception as exc:
        for relpath in reversed(changed):
            dest = root / relpath
            previous = backup / relpath
            if previous.is_file():
                shutil.copy2(previous, dest)
            elif dest.exists():
                dest.unlink()
        print(f"INSTALL FAILED; applied files rolled back: {exc}", file=sys.stderr)
        return 1

    print("SUCCESS: AssignHub Notification Center installed.")
    for relpath in existing:
        print("  UPDATED: " + relpath)
    for relpath in added:
        print("  ADDED: " + relpath)
    print("Backup folder: " + str(backup))
    print("\nNEXT STEPS:")
    print("  python manage.py migrate notifications")
    print("  python manage.py check")
    print("  python manage.py makemigrations --check --dry-run notifications")
    print("  python manage.py test notifications")
    print("  python manage.py test assignments.test_auto_plagiarism accounts")
    print("  Restart Django server and existing plagiarism worker.")
    print("  Deadline reminders: python manage.py send_deadline_notifications")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
